CREATE COLUMN TABLE "TEST_AP"."CUMI" ("Id_" INTEGER CS_INT DEFAULT 0 NOT NULL , "Name_" NVARCHAR(100), "UserSign" SMALLINT CS_INT NOT NULL , "FatherId" INTEGER CS_INT DEFAULT -1, "SortNum" INTEGER CS_INT, "Type_" NVARCHAR(1) DEFAULT '-', "ObjType" NVARCHAR(20), "Key_" NVARCHAR(50), "FormMenuId" INTEGER CS_INT, "FormNum" INTEGER CS_INT, "RepPath" NCLOB MEMORY THRESHOLD 1000, "Levels" SMALLINT CS_INT DEFAULT 1, PRIMARY KEY ("UserSign", "Id_")) UNLOAD PRIORITY 5  AUTO MERGE ;
ALTER TABLE "TEST_AP"."CUMI" WITH PARAMETERS ('CONCAT_ATTRIBUTE'=('$UserSign$Name_$Levels$FatherId$SortNum$','UserSign','Name_','Levels','FatherId','SortNum'));
CREATE INDEX "CUMI_DETAIL" ON "TEST_AP"."CUMI" ( "UserSign" ASC, "Name_" ASC, "Levels" ASC, "FatherId" ASC, "SortNum" ASC )